function newArrayBuffer(bytes: number[]): ArrayBuffer {
  const ab = new ArrayBuffer(bytes.length),
    ua = new Uint8Array(ab);
  for (let i = 0; i < ua.length; i++) {
    ua[i] = bytes[i];
  }
  return ab;
}

const toPackedTests = [
  {
    name: "4-byte Input",
    inputs: {
