      b64: "QUJDRA==",
      arrayBuffer: newArrayBuffer([0x41, 0x42, 0x43, 0x44]),
      uint8Array: Uint8Array.from([0x41, 0x42, 0x43, 0x44]),
      existing: [0x45000000],
      existingMod: [0x00000045],
      lengthExisting: 8,
    },
    outputs: {
      original: [0x41424344],
